examples.template:
MonarchCursorList(
    items = requests,
    label = {{label}},
    hasMore = true,
    onLoadMore = {},
    modifier = Modifier.height(480.dp),
    key = { it.id },
    totalCount = {{total}},
    labels = MonarchCursorListLabels(
        footer = MonarchLoadMoreLabels(
            count = { loaded, total -> "Showing $loaded of ${total ?: loaded} " + if (total == 1) {{noun.one}} else {{noun.other}} },
        ),
    ),
) { request ->
    MonarchListRow(
        headlineContent = {
            Row(
                horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                MonarchText(text = request.method, style = MonarchTextStyle.Caption, color = MonarchTheme.colors.textMuted)
                MonarchText(text = request.path, modifier = Modifier.weight(1f))
                MonarchText(
                    text = request.status.toString(),
                    color = if (request.status >= 400) MonarchTheme.colors.dangerStrong else MonarchTheme.colors.textMuted,
                )
            }
        },
        divider = true,
    )
}

